def main() -> None:
    out = []
    for rel, rows in (("people", PEOPLE), ("cities", CITIES), ("companies", COMPANIES), ("landmarks", LANDMARKS), ("films", FILMS)):
        for bridge, ans, descs, pop, reveals in rows:
            assert len(descs) == 2, bridge
            out.append({"relation": rel, "bridge": bridge, "answer": ans, "answer_aliases": ALIASES.get(rel, {}).get(ans, []),
                        "descriptions": [{"noun": n, "clause": c} for n, c, _ in descs], "skip_cues": [s for _, _, s in descs],
                        "popularity": pop, "name_reveals_answer": reveals, "bridge_alts": BRIDGE_ALTS.get(bridge, [])})  # fmt: skip
    path = Path(__file__).resolve().parents[1] / "data" / "v3_bridges.json"
    path.write_text(json.dumps(out, indent=1, ensure_ascii=False) + "\n")
    print(len(out), "bridges ->", path)


if __name__ == "__main__":
    main()
